const envios = [
  { id: 101, destino: "Palermo",       peso: 12.5, estado: "entregado" },
  { id: 102, destino: "Flores",        peso: 48.0, estado: "demorado" },
  { id: 103, destino: "Flores",        peso: 5.2,  estado: "entregado" },
  { id: 104, destino: "Caballito",     peso: 27.8, estado: "en camino" },
  { id: 105, destino: "Palermo",       peso: 31.0, estado: "demorado" },
  { id: 106, destino: "Puerto Madero", peso: 8.4,  estado: "entregado" },
  { id: 107, destino: "Caballito",     peso: 19.9, estado: "en camino" },
  { id: 108, destino: "Flores",        peso: 22.3, estado: "demorado" },
];

// Imperativo: yo escribo el camino (recorrer, mirar cada uno, anotar)
const a = [];
for (let i = 0; i < envios.length; i++) {
  if (envios[i].estado === "demorado" && envios[i].peso > 25) {
    a.push(envios[i].id);
  }
}

// Más declarativo: yo escribo la condición y el recorrido lo hace filter
const b = envios
  .filter((e) => e.estado === "demorado" && e.peso > 25)
  .map((e) => e.id);

console.log("con bucle: ", a);
console.log("con filter:", b);
